package id.roomfinds.api;

import jakarta.servlet.http.HttpSession;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api")
public class RoomManagementController {
    private final JdbcTemplate db;
    public RoomManagementController(JdbcTemplate db) { this.db=db; }
    private long user(HttpSession s) { Object value=s.getAttribute("userId"); if(value==null) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"Silakan masuk untuk melanjutkan."); return (long)value; }
    private void owner(HttpSession s) { if(!"PEMILIK".equals(s.getAttribute("role"))) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Menu ini hanya tersedia untuk pemilik kos."); }
    private long ownerId(HttpSession s) { owner(s); return user(s); }
    private void requireOwnedKos(long kosId,long ownerId) { if(db.queryForObject("SELECT COUNT(*) FROM kos WHERE id=? AND pemilik_id=?",Long.class,kosId,ownerId)==0) throw new IllegalArgumentException("Kos tidak ditemukan atau kamu tidak memiliki akses."); }
    @PutMapping("/kos/{id}") Map<String,Object> updateKos(HttpSession s,@PathVariable long id,@RequestBody Map<String,Object> b) { long uid=ownerId(s); requireOwnedKos(id,uid); db.update("UPDATE kos SET nama=?,alamat=?,kode_pos=?,aturan_kos=?,tanggal_jatuh_tempo=? WHERE id=? AND pemilik_id=?",b.get("nama"),b.get("alamat"),b.get("kodePos"),b.get("aturanKos"),b.get("tanggalJatuhTempo"),id,uid); return db.queryForMap("SELECT * FROM kos WHERE id=? AND pemilik_id=?",id,uid); }
    @DeleteMapping("/kos/{id}") ResponseEntity<Void> deleteKos(HttpSession s,@PathVariable long id) { owner(s); int n=db.update("DELETE FROM kos WHERE id=? AND pemilik_id=? AND NOT EXISTS (SELECT 1 FROM kamar km WHERE km.kos_id=kos.id AND km.status='TERISI')",id,user(s)); if(n==0) throw new IllegalArgumentException("Kos tidak ditemukan atau masih memiliki kamar terisi."); return ResponseEntity.noContent().build(); }
    @GetMapping("/kos/{kosId}/kamar") List<Map<String,Object>> rooms(HttpSession s,@PathVariable long kosId) { long uid=ownerId(s); requireOwnedKos(kosId,uid); return db.queryForList("SELECT * FROM kamar WHERE kos_id=? ORDER BY nomor",kosId); }
    @PostMapping("/kos/{kosId}/kamar") Map<String,Object> addRoom(HttpSession s,@PathVariable long kosId,@RequestBody Map<String,Object> b) { owner(s); db.queryForObject("SELECT id FROM kos WHERE id=? AND pemilik_id=?",Long.class,kosId,user(s)); return db.queryForMap("INSERT INTO kamar(kos_id,nomor,tipe,harga_bulanan,luas,fasilitas) VALUES(?,?,?,?,?,?::jsonb) RETURNING *",kosId,b.get("nomor"),b.get("tipe"),b.get("hargaBulanan"),b.get("luas"),b.getOrDefault("fasilitas","[]")); }
    @PutMapping("/kos/{kosId}/kamar/{roomId}") Map<String,Object> updateRoom(HttpSession s,@PathVariable long kosId,@PathVariable long roomId,@RequestBody Map<String,Object> b) { long uid=ownerId(s); int changed=db.update("UPDATE kamar km SET nomor=?,tipe=?,harga_bulanan=?,luas=?,fasilitas=?::jsonb FROM kos k WHERE km.id=? AND km.kos_id=k.id AND k.id=? AND k.pemilik_id=?",b.get("nomor"),b.get("tipe"),b.get("hargaBulanan"),b.get("luas"),b.getOrDefault("fasilitas","[]"),roomId,kosId,uid); if(changed==0) throw new IllegalArgumentException("Kamar tidak ditemukan atau kamu tidak memiliki akses."); return db.queryForMap("SELECT km.* FROM kamar km JOIN kos k ON k.id=km.kos_id WHERE km.id=? AND k.pemilik_id=?",roomId,uid); }
    @DeleteMapping("/kos/{kosId}/kamar/{roomId}") ResponseEntity<Void> deleteRoom(HttpSession s,@PathVariable long kosId,@PathVariable long roomId) { owner(s); int n=db.update("DELETE FROM kamar km USING kos k WHERE km.id=? AND km.kos_id=? AND km.kos_id=k.id AND k.pemilik_id=? AND km.status='KOSONG'",roomId,kosId,user(s)); if(n==0) throw new IllegalArgumentException("Kamar tidak ditemukan atau masih dipesan/terisi."); return ResponseEntity.noContent().build(); }
    @GetMapping("/kos/{kosId}/paket") List<Map<String,Object>> packages(HttpSession s,@PathVariable long kosId) { return db.queryForList("SELECT id,kos_id AS \"kosId\",nama,durasi_bulan AS \"durasiBulan\",persen_diskon AS \"persenDiskon\",aktif FROM paket_sewa WHERE kos_id=? AND aktif=true ORDER BY durasi_bulan",kosId); }
    @PutMapping("/kos/{kosId}/paket") @Transactional List<Map<String,Object>> updatePackages(HttpSession s,@PathVariable long kosId,@RequestBody List<Map<String,Object>> list) { owner(s); db.queryForObject("SELECT id FROM kos WHERE id=? AND pemilik_id=?",Long.class,kosId,user(s)); for(var p:list) db.update("UPDATE paket_sewa SET persen_diskon=?,aktif=? WHERE kos_id=? AND nama=?",p.get("persenDiskon"),p.get("aktif"),kosId,p.get("nama")); return db.queryForList("SELECT * FROM paket_sewa WHERE kos_id=? ORDER BY durasi_bulan",kosId); }
    @PutMapping("/kos/{id}/aturan-denda") Map<String,Object> penalty(HttpSession s,@PathVariable long id,@RequestBody Map<String,Object> b) { long uid=ownerId(s); try { String json=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(b); int changed=db.update("UPDATE kos SET aturan_denda=?::jsonb WHERE id=? AND pemilik_id=?",json,id,uid); if(changed==0) throw new IllegalArgumentException("Kos tidak ditemukan atau kamu tidak memiliki akses."); return db.queryForMap("SELECT aturan_denda AS \"aturanDenda\" FROM kos WHERE id=? AND pemilik_id=?",id,uid); } catch(com.fasterxml.jackson.core.JsonProcessingException e) { throw new IllegalArgumentException("Aturan denda tidak valid."); } }
    @PostMapping("/kos/{kosId}/tagihan/terbitkan") @Transactional List<Map<String,Object>> issueBills(HttpSession s,@PathVariable long kosId,@RequestParam String periode) { long uid=ownerId(s); requireOwnedKos(kosId,uid); LocalDate month=LocalDate.parse(periode+"-01"); Number dueDay=db.queryForObject("SELECT tanggal_jatuh_tempo FROM kos WHERE id=?",Number.class,kosId); LocalDate due=month.withDayOfMonth(Math.min(dueDay.intValue(),month.lengthOfMonth())); List<Map<String,Object>> created=new java.util.ArrayList<>(); for(var row:db.queryForList("SELECT b.id AS booking_id,km.nomor,km.harga_bulanan FROM booking b JOIN kamar km ON km.id=b.kamar_id WHERE km.kos_id=? AND b.status='DISETUJUI' ORDER BY km.nomor",kosId)) { if(db.queryForObject("SELECT COUNT(*) FROM tagihan WHERE booking_id=? AND periode=?",Long.class,row.get("booking_id"),month)>0) continue; long sewa=((Number)row.get("harga_bulanan")).longValue(); Long tid=db.queryForObject("INSERT INTO tagihan(booking_id,periode,jatuh_tempo,subtotal_item,denda,total,status) VALUES(?,?,?,?,0,?,'BELUM_BAYAR') RETURNING id",Long.class,row.get("booking_id"),month,due,sewa,sewa); db.update("INSERT INTO item_tagihan(tagihan_id,jenis,keterangan,subtotal) VALUES(?,'SEWA','Sewa kamar',?)",tid,sewa); created.add(db.queryForMap("SELECT t.id,t.booking_id AS \"bookingId\",t.periode,t.jatuh_tempo AS \"jatuhTempo\",t.total,t.status,km.nomor AS \"kamarNomor\" FROM tagihan t JOIN booking b ON b.id=t.booking_id JOIN kamar km ON km.id=b.kamar_id WHERE t.id=?",tid)); } return created; }
    @GetMapping("/kos/{kosId}/laporan") Map<String,Object> report(HttpSession s,@PathVariable long kosId,@RequestParam(required=false) String periode) { long uid=ownerId(s); requireOwnedKos(kosId,uid); var m=db.queryForMap("SELECT COALESCE((SELECT SUM(jumlah) FROM pembayaran p JOIN tagihan t ON t.id=p.tagihan_id JOIN booking b ON b.id=t.booking_id JOIN kamar km ON km.id=b.kamar_id WHERE km.kos_id=? AND p.status='DITERIMA' AND (? IS NULL OR to_char(t.periode,'YYYY-MM')=?)),0) AS pendapatan,COALESCE((SELECT SUM(t.total-t.terbayar) FROM tagihan t JOIN booking b ON b.id=t.booking_id JOIN kamar km ON km.id=b.kamar_id WHERE km.kos_id=? AND t.status<>'LUNAS' AND (? IS NULL OR to_char(t.periode,'YYYY-MM')=?)),0) AS tunggakan,(SELECT COUNT(*) FROM kamar WHERE kos_id=? AND status='TERISI') AS \"kamarTerisi\",(SELECT COUNT(*) FROM kamar WHERE kos_id=?) AS \"jumlahKamar\"",kosId,periode,periode,kosId,periode,periode,kosId,kosId); m.put("periode",periode==null?LocalDate.now().toString().substring(0,7):periode); return m; }
}
